function linkedSkills(skillPath) {
  const text = fs.readFileSync(path.join(skillPath, "SKILL.md"), "utf8");
  return [...text.matchAll(/\[\[([a-z0-9-]+)\]\]/g)].map((match) => match[1]);
}
